import { message } from 'antd';
import requestService from 'api/request';
import clsx from 'clsx'
import { SubmitHandler, useForm } from 'react-hook-form';
import { useNavigate } from 'react-router-dom';
import { useAuthApp } from 'store/useAuthApp';
import { useGlobalAppStore } from 'store/useGlobalApp';

interface IFormInput {
    phone: string;
    password: string;
    payment_password: string;
    inviteCode: string,
    isCheckPolicy: boolean
}


const Register = () => {
    const { loading, handleLoading } = useGlobalAppStore()
    const { onSetUser } = useAuthApp()
    const navigate = useNavigate()
    const { register, handleSubmit, watch, control, setValue, formState: { errors } } = useForm<IFormInput>({
        defaultValues: {
            isCheckPolicy: false
        }
    });
    const isCheckPolicy = watch('isCheckPolicy')
    const payment_password = watch('payment_password')

    const onSubmit: SubmitHandler<IFormInput> = async (data) => {
        handleLoading(true)
        try {
            const res = await requestService.post('/auth/register', {
                data: {
                    ...data
                }
            })
            if (res && res.data) {

                localStorage.setItem(
                    "accessToken",
                    res?.data?.data?.tokens?.accessToken
                );
                localStorage.setItem(
                    "refreshToken",
                    res?.data?.data?.tokens?.refreshToken
                );
                onSetUser(res?.data?.data?.user)
                message.success(res?.data?.message)
                setTimeout(() => {
                    handleLoading(false)
                    navigate('/')
                }, 1000)

            }
        } catch (error: any) {
            message.error(error?.response?.data?.message)
            handleLoading(false)
        }

    };


    return (
        <div data-v-fed939fe="" data-v-daf86cc3="" className="register-content">
            <div data-v-fed939fe="" className="title">
                Tạo tài khoản mới
            </div>
            <form data-v-fed939fe="" className={clsx("register-form")} onSubmit={handleSubmit(onSubmit)}>
                <div data-v-fed939fe="" className="form-item">
                    <div data-v-fed939fe="" className="van-cell van-field">
                        <div className="van-field__left-icon">
                            <div data-v-fed939fe="" className="country-code">
                                +84
                            </div>
                        </div>
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body">
                                <input
                                    type="tel"
                                    inputMode="numeric"
                                    id="van-field-52-input"
                                    className="van-field__control"
                                    placeholder="Số điện thoại di động"
                                    autoComplete="tel"
                                    data-allow-mismatch="attribute"
                                    {...register("phone", {
                                        required: "phone_required",
                                        pattern: {
                                            value: /^(0[1-9]\d{8})$|^(0?\d{9})$|^(?:\d{3}[-\s]?\d{3}[-\s]?\d{4})$|^(?:\(\d{3}\)[-\s]?\d{3}[-\s]?\d{4})$/
                                            ,
                                            message: "invalid_phone_number_format"
                                        }

                                    })}
                                />

                            </div>
                            {/**/}
                            {/**/}
                        </div>
                        {/**/}
                        {/**/}
                    </div>
                    {errors.phone && <p className='pl-2 text-red-600 text-[12px]'>{errors.phone.message}</p>}
                </div>
                {/**/}
                <div data-v-fed939fe="" className="form-item">
                    <div data-v-fed939fe="" className="van-cell van-field">
                        <div className="van-field__left-icon">
                            <i className="van-badge__wrapper van-icon van-icon-shield-o">
                                {/**/}
                                {/**/}
                                {/**/}
                            </i>
                        </div>
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body">
                                <input
                                    type="password"
                                    id="van-field-53-input"
                                    className="van-field__control"
                                    placeholder="Mật khẩu"
                                    autoComplete="new-password"
                                    data-allow-mismatch="attribute"
                                    {...register("password", {
                                        required: "password_required",

                                    })}
                                />

                                {/**/}
                                <div className="van-field__right-icon">
                                    <i className="van-badge__wrapper van-icon van-icon-closed-eye">

                                    </i>
                                </div>
                                {/**/}
                            </div>

                        </div>
                        {/**/}
                        {/**/}
                    </div>
                    {errors.password && <p className='pl-2 text-red-600 text-[12px]'>{errors.password.message}</p>}
                </div>
                <div data-v-fed939fe="" className="form-item">
                    <div
                        data-v-fed939fe=""
                        className="van-cell van-field payment-password"
                    >
                        <div className="van-field__left-icon">
                            <i className="van-badge__wrapper van-icon van-icon-lock">

                            </i>
                        </div>
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body">
                                <input
                                    type="tel"
                                    inputMode="numeric"
                                    id="van-field-54-input"
                                    className="van-field__control"
                                    placeholder="Mật khẩu thanh toán"
                                    autoComplete="new-password"
                                    data-allow-mismatch="attribute"
                                    disabled={payment_password?.length === 6}
                                    {...register("payment_password", {
                                        required: "payment_password_required",
                                        pattern: {
                                            value: /^[A-Za-z0-9]{1,6}$/,
                                            message: "payment_password_maximum_6_characters"
                                        }
                                    })}
                                />

                            </div>
                            <div className="van-field__word-limit">
                                <span className="van-field__word-num">{payment_password?.length || 0}</span>/6
                            </div>
                            {/**/}
                        </div>
                        {/**/}
                        {/**/}
                    </div>
                    {errors.payment_password && <p className='pl-2 text-red-600 text-[12px]'>{errors.payment_password.message}</p>}
                </div>
                <div data-v-fed939fe="" className="form-item">
                    <div data-v-fed939fe="" className="van-cell van-field">
                        <div className="van-field__left-icon">
                            <i className="van-badge__wrapper van-icon van-icon-friends-o">
                                {/**/}
